  [2339]={n="Find the Gems and Power Source",c="寻找宝贝",lv=44,req=37,side="H",share=false,d="uldaman",wing="",cls={},st={k="npc",id=6868,n="Jarkal Mossmeld",c="加卡尔",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=2.6,y=46},fi={k="npc",id=6868,n="Jarkal Mossmeld",c="加卡尔",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=2.6,y=46},stText="",stTextC="",pre={2338},preAny={},chain={},bread=false,o="Recover all three gems and a power source for the necklace from Uldaman , and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman . From the journal, you know... * The ruby has been stashed in a barricaded Shadowforge area. * The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves. * The sapphire has been claimed by Grimlok, the trogg leader.",oc="从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。$B$B红宝石被藏在暗影矮人层层设防的地区。$B$B黄宝石藏在石腭怪活动地区的一个瓮中。$B$B蓝宝石在格瑞姆洛克手中，他是石腭怪的领袖。$B$B能量源可能在奥达曼的某个最强生物的手中。",goals={{k="item",id=7669,n="Shattered Necklace Ruby",c="破碎项链上的红宝石",cnt=1},{k="item",id=7670,n="Shattered Necklace Sapphire",c="破碎项链上的蓝宝石",cnt=1},{k="item",id=7671,n="Shattered Necklace Topaz",c="破碎项链上的黄宝石",cnt=1},{k="item",id=7672,n="Shattered Necklace Power Source",c="破碎项链的能量源",cnt=1}},r={},ch={},xp=3750,money=0,changed="",changedc="",new=false,drop=false,rep={{"暗矛巨魔",100}}},
  [2340]={n="Deliver the Gems",c="交付宝石",lv=44,req=37,side="H",share=false,d="uldaman",wing="",cls={},st={k="npc",id=6868,n="Jarkal Mossmeld",c="加卡尔",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=2.6,y=46},fi={k="npc",id=6986,n="Dran Droffers",c="德兰·杜佛斯",z=1637,zc="奥格瑞玛",ze="Orgrimmar",ui=1454,x=59.4,y=36.8},stText="",stTextC="",pre={2339},preAny={},chain={2340,2341},bread=false,o="Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.",oc="把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。",goals={{k="item",id=7887,n="Necklace and Gem Salvage",c="项链和珠宝",cnt=1}},r={},ch={},xp=1850,money=12500,changed="",changedc="",new=false,drop=false,rep={{"奥格瑞玛",50}}},
