  [4023]={n="A Taste of Flame",c="烈焰精华",lv=54,req=52,side="B",share=false,d="",wing="",cls={},st={k="npc",id=9459,n="Cyrus Therepentous",c="塞勒斯·萨雷芬图斯",z=46,zc="燃烧平原",ze="Burning Steppes",ui=1428,x=94.8,y=31.6},fi={k="npc",id=9459,n="Cyrus Therepentous",c="塞勒斯·萨雷芬图斯",z=46,zc="燃烧平原",ze="Burning Steppes",ui=1428,x=94.8,y=31.6},stText="",stTextC="",pre={},preAny={},chain={4022,4023,4024},bread=false,o="Show Cyrus Therepentous proof of your worth. You have a feeling that Cyrus already knows that you are unworthy.",oc="向塞勒斯·萨雷芬图斯证明你的价值。$B$B你感觉到塞勒斯似乎对你不屑一顾。",goals={},r={},ch={},xp=5450,money=0,changed="",changedc="",new=false,drop=false,rep={}},
  [4024]={n="A Taste of Flame",c="烈焰精华",lv=58,req=52,side="B",share=false,d="brd",wing="",cls={},st={k="npc",id=9459,n="Cyrus Therepentous",c="塞勒斯·萨雷芬图斯",z=46,zc="燃烧平原",ze="Burning Steppes",ui=1428,x=94.8,y=31.6},fi={k="npc",id=9459,n="Cyrus Therepentous",c="塞勒斯·萨雷芬图斯",z=46,zc="燃烧平原",ze="Burning Steppes",ui=1428,x=94.8,y=31.6},stText="Burning Steppes, Cave in NE",stTextC="燃烧平原，东北边的山洞",pre={},preAny={4022,4023},chain={4022,4023,4024},bread=false,o="Travel to Blackrock Depths and slay Bael'Gar. You only know that the giant resides inside Blackrock Depths . Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence. Return the Encased Fiery Essence to Cyrus Therepentous .",oc="到黑石深渊去杀掉贝尔加。$B$B你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。$B$B将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。",goals={{k="item",id=11230,n="Encased Fiery Essence",c="包起来的烈焰精华",cnt=1}},r={},ch={},xp=6200,money=26500,changed="Rewards: no longer Choice of Shaleskin Cape, Choice of Valconian Sash, Choice of Wyrmhide Spaulders",changedc="奖励去掉：可选 页岩斗篷、可选 火山腰带、可选 龙皮肩铠",new=false,drop=false,rep={}},
  [4061]={n="The Rise of the Machines",c="机器的崛起",lv=54,req=52,side="H",share=false,d="",wing="",cls={},st={k="npc",id=9079,n="Hierophant Theodora Mulvadania",c="塞朵拉·穆瓦丹尼",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=3,y=47.8},fi={k="npc",id=9079,n="Hierophant Theodora Mulvadania",c="塞朵拉·穆瓦丹尼",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=3,y=47.8},stText="",stTextC="",pre={},preAny={},chain={4061,4062,4063},bread=false,o="Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania . You recall Theodora mentioning the golems and elementals of that region as being a source for these shards.",oc="到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。$b$b塞朵拉曾经说过，那里的机械傀儡和元素生物是这种碎片的主要来源。",goals={},r={},ch={},xp=5450,money=16500,changed="",changedc="",new=false,drop=false,rep={{"幽暗城",100}}},
  [4062]={n="The Rise of the Machines",c="机器的崛起",lv=54,req=52,side="H",share=false,d="",wing="",cls={},st={k="npc",id=9079,n="Hierophant Theodora Mulvadania",c="塞朵拉·穆瓦丹尼",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=3,y=47.8},fi={k="npc",id=2921,n="Lotwil Veriatus",c="鲁特维尔·沃拉图斯",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=25.8,y=45},stText="",stTextC="",pre={4061},preAny={},chain={4061,4062,4063},bread=false,o="Take the Elemental Shard Sample to Lotwil Veriatus . You recall Theodora saying that Lotwil was stationed in a camp to the east.",oc="将元素碎片样本交给鲁特维尔·沃拉图斯。$B$B塞朵拉说鲁特维尔就在东边的一处营地里。",goals={},r={},ch={},xp=1350,money=0,changed="",changedc="",new=false,drop=false,rep={}},
  [4063]={n="The Rise of the Machines",c="机器的崛起",lv=58,req=52,side="H",share=true,d="brd",wing="",cls={},st={k="npc",id=2921,n="Lotwil Veriatus",c="鲁特维尔·沃拉图斯",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=25.8,y=45},fi={k="npc",id=2921,n="Lotwil Veriatus",c="鲁特维尔·沃拉图斯",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=25.8,y=45},stText="Badlands, Eastern",stTextC="荒芜之地，东边",pre={4062},preAny={},chain={4061,4062,4063},bread=false,o="Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",oc="找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。",goals={{k="item",id=11268,n="Head of Argelmach",c="阿格曼奇的头颅",cnt=1},{k="item",id=11269,n="Intact Elemental Core",c="完整的元素核心",cnt=10}},r={},ch={},xp=6200,money=26500,changed="Rewards: no longer Choice of Azure Moon Amice, Choice of Basaltscale Armor, Choice of Lavaplate Gauntlets, and 1 more",changedc="奖励去掉：可选 蓝月披肩、可选 黑陶鳞片护甲、可选 熔岩护手、and 1 more",new=false,drop=false,rep={}},
  [4081]={n="KILL ON SIGHT: Dark Iron Dwarves",c="格杀勿论：黑铁矮人",lv=52,req=48,side="H",share=true,d="brd",wing="",cls={},st={k="object",id=164867,n="WANTED",c="通缉",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=3.8,y=47.5},fi={k="npc",id=9077,n="Warlord Goretooth",c="军官高图斯",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=5.8,y=47.4},stText="Badlands, Kargath - an object poster",stTextC="荒芜之地，卡加斯 - 一张告示",pre={},preAny={},chain={},bread=false,o="Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.",oc="到黑石深渊去消灭那些邪恶的侵略者！$B$B军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。",goals={{k="kill",id=8891,n="Anvilrage Guardsman",c="铁怒卫士",cnt=15},{k="kill",id=8890,n="Anvilrage Warden",c="铁怒狱卒",cnt=10},{k="kill",id=8892,n="Anvilrage Footman",c="铁怒步兵",cnt=5}},r={},ch={},xp=5100,money=15500,changed="",changedc="",new=false,drop=false,rep={{"奥格瑞玛",100}}},
  [4082]={n="KILL ON SIGHT: High Ranking Dark Iron Officials",c="格杀勿论：高阶黑铁军官",lv=54,req=50,side="H",share=true,d="brd",wing="",cls={},st={k="object",id=164868,n="KILL ON SIGHT",c="格杀勿论",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=4,y=46.8},fi={k="npc",id=9077,n="Warlord Goretooth",c="军官高图斯",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=5.8,y=47.4},stText="Badlands, Kargath - an object poster",stTextC="荒芜之地，卡加斯 - 一张告示",pre={4081},preAny={},chain={},bread=false,o="Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 10 Anvilrage Medics , 10 Anvilrage Soldiers and 10 Anvilrage Officers . Return to him once your task is complete.",oc="到黑石深渊去消灭那些邪恶的侵略者！$B$B高图斯军阀要你杀死10个铁怒医师,、10个铁怒士兵和10个铁怒军官。完成任务之后回去向他复命。",goals={{k="kill",id=8894,n="Anvilrage Medic",c="铁怒医师",cnt=10},{k="kill",id=8893,n="Anvilrage Soldier",c="铁怒士兵",cnt=10},{k="kill",id=8895,n="Anvilrage Officer",c="铁怒军官",cnt=10}},r={},ch={},xp=5450,money=16500,changed="",changedc="",new=false,drop=false,rep={{"奥格瑞玛",100}}},
