  [4121]={n="Precarious Predicament",c="押送囚徒",lv=58,req=52,side="H",share=false,d="brd",wing="",cls={},st={k="npc",id=9520,n="Grark Lorkrub",c="格拉克·洛克鲁布",z=46,zc="燃烧平原",ze="Burning Steppes",ui=1428,x=40.2,y=34.2},fi={k="npc",id=9080,n="Lexlort",c="雷克斯洛特",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=5.8,y=47.6},stText="",stTextC="",pre={4122},preAny={},chain={},bread=false,o="Escort your prisoner, Grark Lorkrub , through Burning Steppes and through Blackrock Mountain to the Searing Gorge. You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody. You will also be required to hand over your Thorium Shackles to Lexlort .",oc="押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。$B$B雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。$B$B另外，你还要把瑟银镣铐一并还给雷克斯洛特。",goals={{k="item",id=11286,n="Thorium Shackles",c="瑟银镣铐",cnt=1},{k="text",id=0,n="Prisoner Transport",c="押送囚犯",cnt=1}},r={},ch={},xp=7750,money=26500,changed="",changedc="",new=false,drop=false,rep={{"奥格瑞玛",150}}},
  [4122]={n="Grark Lorkrub",c="格拉克·洛克鲁布",lv=58,req=52,side="H",share=false,d="brd",wing="",cls={},st={k="npc",id=9080,n="Lexlort",c="雷克斯洛特",z=3,zc="荒芜之地",ze="Badlands",ui=1418,x=5.8,y=47.6},fi={k="npc",id=9520,n="Grark Lorkrub",c="格拉克·洛克鲁布",z=46,zc="燃烧平原",ze="Burning Steppes",ui=1428,x=40.2,y=34.2},stText="",stTextC="",pre={},preAny={},chain={},bread=false,o="Travel to the Burning Steppes and find Grark Lorkrub . You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress. When you find Grark Lorkrub , use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody. Provided item:",oc="到燃烧平原去找到格拉克·洛克鲁布。你回忆起雷克斯洛特曾经提起过，格拉克应该是在一座大型的黑石要塞中。$B$B当你找到格拉克·洛克鲁布之后，用瑟银镣铐把他铐起来，然后将其带回灼热峡谷。雷克斯洛特会让他的部下等在那里接应你。",goals={{k="item",id=11286,n="Thorium Shackles",c="瑟银镣铐",cnt=1}},r={},ch={},xp=6200,money=0,changed="",changedc="",new=false,drop=false,rep={}},
