  [4742]={n="Seal of Ascension",c="晋升印章",lv=60,req=57,side="B",share=true,d="lbrs",wing="",cls={},st={k="npc",id=10299,n="Scarshield Infiltrator",c="裂盾渗透者",z=1583,zc="黑石塔",ze="Blackrock Spire",ui=0,x=0,y=0,i=true},fi={k="npc",id=10299,n="Scarshield Infiltrator",c="裂盾渗透者",z=1583,zc="黑石塔",ze="Blackrock Spire",ui=0,x=0,y=0,i=true},stText="Blackrock Spire, Lower - Unadorned Seal of Ascension, Gemstone of Smolderthorn, Gemstone of Spirestone, Gemstone of Bloodaxe",stTextC="黑石塔，下层 - 朴素的晋升印章，烟棘宝石，尖石宝石，血斧宝石",pre={},preAny={},chain={4742,4743},bread=false,o="Find the three gemstones of command: The Gemstone of Smolderthorn , Gemstone of Spirestone , and Gemstone of Bloodaxe . Return them, along with the Unadorned Seal of Ascension , to Vaelan. The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe.",oc="找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。$B$B可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。",goals={{k="item",id=12336,n="Gemstone of Spirestone",c="尖石宝钻",cnt=1},{k="item",id=12335,n="Gemstone of Smolderthorn",c="燃棘宝钻",cnt=1},{k="item",id=12337,n="Gemstone of Bloodaxe",c="血斧宝钻",cnt=1},{k="item",id=12219,n="Unadorned Seal of Ascension",c="原始晋升印章",cnt=1}},r={},ch={},xp=8300,money=0,changed="",changedc="",new=false,drop=true,rep={}},
  [4743]={n="Seal of Ascension",c="晋升印章",lv=60,req=57,side="B",share=false,d="lbrs",wing="",cls={},st={k="npc",id=10299,n="Scarshield Infiltrator",c="裂盾渗透者",z=1583,zc="黑石塔",ze="Blackrock Spire",ui=0,x=0,y=0,i=true},fi={k="npc",id=10299,n="Scarshield Infiltrator",c="裂盾渗透者",z=1583,zc="黑石塔",ze="Blackrock Spire",ui=0,x=0,y=0,i=true},stText="",stTextC="",pre={4742},preAny={},chain={4742,4743},bread=false,o="Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken. It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!",oc="到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。$B$B此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！",goals={{k="item",id=12324,n="Forged Seal of Ascension",c="铸造好的晋升印章",cnt=1}},r={},ch={},xp=9950,money=0,changed="Rewards: no longer Seal of Ascension",changedc="奖励去掉：晋升印章",new=false,drop=false,rep={}},
