  [5282]={n="The Restless Souls",c="永不安息的灵魂",lv=60,req=55,side="B",share=false,d="stratholme",wing="living",cls={},st={k="npc",id=11140,n="Egan",c="埃根",z=139,zc="东瘟疫之地",ze="Eastern Plaguelands",ui=1423,x=14.4,y=33.6},fi={k="npc",id=11140,n="Egan",c="埃根",z=139,zc="东瘟疫之地",ze="Eastern Plaguelands",ui=1423,x=14.4,y=33.6},stText="Eastern Plaguelands, Terrordale",stTextC="东瘟疫之地，恐惧谷",pre={5281},preAny={},chain={5281,5282},bread=false,o="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme . When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 restless souls and return to Egan .",oc="对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！$B$B解放15个永不安息的灵魂，然后回到埃根那里去。",goals={{k="npc",id=11122,n="Souls Freed",c="永不安息的灵魂",cnt=15}},r={},ch={},xp=8300,money=18000,changed="Rewards: no longer Testament of Hope",changedc="奖励去掉：希望的证明",new=false,drop=false,rep={}},
  [5341]={n="Barov Family Fortune",c="巴罗夫家族的宝藏",lv=60,req=52,side="H",share=true,d="scholomance",wing="",cls={},st={k="npc",id=11022,n="Alexi Barov",c="阿莱克斯·巴罗夫",z=85,zc="提瑞斯法林地",ze="Tirisfal Glades",ui=1420,x=83,y=71.4},fi={k="npc",id=11022,n="Alexi Barov",c="阿莱克斯·巴罗夫",z=85,zc="提瑞斯法林地",ze="Tirisfal Glades",ui=1420,x=83,y=71.4},stText="Tirisfal Glades, The Bulwark",stTextC="提瑞斯法林地，亡灵壁垒",pre={},preAny={},chain={5341,5342},bread=false,o="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow ; The Deed to Brill ; The Deed to Tarren Mill ; and The Deed to Southshore . Return to Alexi Barov when you have completed this task.",oc="到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。",goals={{k="item",id=13471,n="The Deed to Brill",c="布瑞尔地契",cnt=1},{k="item",id=13448,n="The Deed to Caer Darrow",c="凯尔达隆地契",cnt=1},{k="item",id=13450,n="The Deed to Southshore",c="南海镇地契",cnt=1},{k="item",id=13451,n="The Deed to Tarren Mill",c="塔伦米尔地契",cnt=1}},r={},ch={},xp=6600,money=18000,changed="",changedc="",new=false,drop=false,rep={}},
  [5342]={n="The Last Barov",c="巴罗夫的继承人",lv=60,req=52,side="H",share=false,d="",wing="",cls={},st={k="npc",id=11022,n="Alexi Barov",c="阿莱克斯·巴罗夫",z=85,zc="提瑞斯法林地",ze="Tirisfal Glades",ui=1420,x=83,y=71.4},fi={k="npc",id=11022,n="Alexi Barov",c="阿莱克斯·巴罗夫",z=85,zc="提瑞斯法林地",ze="Tirisfal Glades",ui=1420,x=83,y=71.4},stText="",stTextC="",pre={5341},preAny={},chain={5341,5342},bread=false,o="Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov . Be warned, Weldon will probably be well protected by Alliance scum.",oc="到冰风岗——联盟的领地——去暗杀维尔顿·巴罗夫。把他的脑袋交给阿莱克斯·巴罗夫。$B$B要多加小心，联盟也许对维尔顿实施了严密的保护。",goals={},r={},ch={},xp=8300,money=18000,changed="",changedc="",new=false,drop=false,rep={}},
