  [6582]={n="The Test of Skulls, Scryer",c="龙骨试炼，斯克利尔",lv=60,req=55,side="H",share=true,d="ubrs",wing="",cls={},st={k="npc",id=10321,n="Emberstrife",c="埃博斯塔夫",z=0,zc="尘泥沼泽",ze="Dustwallow Marsh",ui=1445,x=56.7,y=87.7},fi={k="npc",id=10321,n="Emberstrife",c="埃博斯塔夫",z=0,zc="尘泥沼泽",ze="Dustwallow Marsh",ui=1445,x=56.7,y=87.7},stText="",stTextC="",pre={},preAny={},chain={},bread=false,o="You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.$B$BYou know that Scryer can be found in Winterspring.",oc="找到蓝龙斯克利尔并杀掉他。从他的身上取下他的颅骨，然后将其交给埃博斯塔夫。$B$B你可以在冬泉谷找到斯克利尔。",goals={{k="text",id=0,n="You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and...",c="找到蓝龙军团的精英幼龙斯克瑞尔并杀死它，从尸体上撬下头骨交给埃博斯塔夫。",cnt=1}},r={},ch={},xp=0,money=0,changed="",changedc="",new=false,drop=false,rep={}},
