  [6601]={n="Ascension...",c="晋升……",lv=60,req=55,side="H",share=false,d="",wing="",cls={},st={k="npc",id=10321,n="Emberstrife",c="埃博斯塔夫",z=15,zc="尘泥沼泽",ze="Dustwallow Marsh",ui=1445,x=56.6,y=87.6},fi={k="npc",id=10182,n="Rexxar",c="雷克萨",z=357,zc="菲拉斯",ze="Feralas",ui=1444,x=45.2,y=2.6},stText="",stTextC="",pre={6585},preAny={},chain={6585,6601,6602},bread=false,o="It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet . Hopefully he will know what to do next.",oc="看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找罗卡鲁，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。",goals={},r={},ch={},xp=4950,money=0,changed="",changedc="",new=false,drop=false,rep={}},
