  [7441]={n="Pusillin and the Elder Azj'Tordin",c="普希林和埃斯托尔迪",lv=58,req=54,side="B",share=true,d="diremaul",wing="east",cls={},st={k="npc",id=14355,n="Azj'Tordin",c="埃斯托尔迪",z=357,zc="菲拉斯",ze="Feralas",ui=1444,x=76.8,y=37.4},fi={k="npc",id=14355,n="Azj'Tordin",c="埃斯托尔迪",z=357,zc="菲拉斯",ze="Feralas",ui=1444,x=76.8,y=37.4},stText="Feralas, Lariss Pavillion",stTextC="菲拉斯，拉瑞斯小亭",pre={},preAny={},chain={},bread=false,o="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin 's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations .",oc="到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。$B$B找到咒术之书后，回到拉瑞斯小亭的埃斯托尔迪那里。",goals={{k="item",id=18261,n="Book of Incantations",c="咒术之书",cnt=1}},r={},ch={},xp=7750,money=17500,changed="Rewards: no longer Choice of Sprinter's Sword, Choice of Spry Boots",changedc="奖励去掉：可选 奔行者之剑、可选 活跃之靴",new=false,drop=false,rep={{"辛德拉",200}}},
  [7461]={n="The Madness Within",c="伊莫塔尔的疯狂",lv=60,req=56,side="B",share=true,d="diremaul",wing="west",cls={},st={k="npc",id=14358,n="Shen'dralar Ancient",c="辛德拉古灵",z=2557,zc="厄运之槌",ze="Dire Maul",ui=0,x=0,y=0,i=true},fi={k="npc",id=14358,n="Shen'dralar Ancient",c="辛德拉古灵",z=2557,zc="厄运之槌",ze="Dire Maul",ui=0,x=0,y=0,i=true},stText="Dire Maul, West, second floor",stTextC="厄运之槌，西边，二楼",pre={},preAny={},chain={7461,7877},bread=false,o="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar . Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated. Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum. Return to the Shen'dralar Ancient in the courtyard should you complete this quest.",oc="你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。$B$B进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。$B$B当任务完成之后，到庭院中去找辛德拉古灵。",goals={{k="kill",id=11496,n="Immol'thar",c="伊莫塔尔",cnt=1},{k="kill",id=11486,n="Prince Tortheldrin",c="托塞德林王子",cnt=1}},r={},ch={},xp=9950,money=0,changed="",changedc="",new=false,drop=false,rep={}},
  [7462]={n="The Treasure of the Shen'dralar",c="辛德拉的宝藏",lv=60,req=56,side="B",share=true,d="diremaul",wing="",cls={},st=nil,fi=nil,stText="",stTextC="",pre={},preAny={},chain={},bread=false,o="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",oc="返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！",goals={},r={},ch={},xp=660,money=27000,changed="Rewards: no longer Choice of Backwood Helm, Choice of Bonecrusher, Choice of Sedge Boots",changedc="奖励去掉：可选 密林头盔、可选 碾骨者、可选 莎草长靴",new=false,drop=false,rep={}},
