  [7507]={n="Foror's Compendium",c="弗洛尔的屠龙技术纲要",lv=60,req=60,side="B",share=false,d="diremaul",wing="west",cls={},st={k="item",id=18401,n="Nostro's Compendium of Dragon Slaying",c="弗洛尔的屠龙技术纲要",z=0,zc="",ze="",ui=0,x=0,y=0},fi={k="npc",id=14368,n="Lorekeeper Lydros",c="博学者莱德罗斯",z=2557,zc="厄运之槌",ze="Dire Maul",ui=0,x=0,y=0,i=true},stText="Dire Maul - Nostro's Compendium of Dragon Slaying, rare drop or looted from an object.",stTextC="厄运之槌 - 诺斯托的屠龙手册，稀有掉落，或从物件里拿",pre={},preAny={},chain={},bread=false,o="Return Foror's Compendium of Dragon Slaying to the Athenaeum.",oc="将《弗洛尔的屠龙技术纲要》还回图书馆。",goals={{k="item",id=18401,n="Nostro's Compendium of Dragon Slaying",c="弗洛尔的屠龙技术纲要",cnt=1}},r={},ch={},xp=9950,money=0,changed="Renamed from Nostro's Compendium; Objective text reworded",changedc="原名「Nostro's Compendium」；任务目标文字改写",new=false,drop=true,rep={{"辛德拉",200}}},
  [7508]={n="The Forging of Quel'Serrar",c="铸造奎尔塞拉",lv=60,req=60,side="B",share=false,d="diremaul",wing="",cls={},st={k="item",id=18513,n="A Dull and Flat Elven Blade",c="黯淡的精灵剑",z=0,zc="",ze="",ui=0,x=0,y=0},fi={k="npc",id=14368,n="Lorekeeper Lydros",c="博学者莱德罗斯",z=2557,zc="厄运之槌",ze="Dire Maul",ui=0,x=0,y=0,i=true},stText="",stTextC="",pre={7507},preAny={},chain={7508,7509},bread=false,o="Give the Dull and Flat Elven Blade to Lorekeeper Lydros .",oc="把黯淡的精灵剑交给博学者莱德罗斯。",goals={{k="item",id=18513,n="A Dull and Flat Elven Blade",c="黯淡的精灵剑",cnt=1}},r={},ch={},xp=0,money=0,changed="",changedc="",new=false,drop=false,rep={}},
  [7509]={n="The Forging of Quel'Serrar",c="铸造奎尔塞拉",lv=60,req=60,side="B",share=false,d="",wing="",cls={"1","2"},st={k="npc",id=14368,n="Lorekeeper Lydros",c="博学者莱德罗斯",z=2557,zc="厄运之槌",ze="Dire Maul",ui=0,x=0,y=0,i=true},fi={k="npc",id=14368,n="Lorekeeper Lydros",c="博学者莱德罗斯",z=2557,zc="厄运之槌",ze="Dire Maul",ui=0,x=0,y=0,i=true},stText="",stTextC="",pre={7508},preAny={},chain={7508,7509},bread=false,o="You must get Onyxia to breathe fire on the Unfired Ancient Blade . Once this is done, pick up the now Heated Ancient Blade . Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence. The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse. Do this and Quel'Serrar will be yours.",oc="你必须设法让奥妮克希亚对这把未淬火的上古之刃喷射火焰。完成之后，捡起加热过的上古之刃。你要注意的是，加热过的上古之刃不会一直保持被加热的状态，时间非常紧迫。$B$B在把它给我拿回来之前的最后一步是杀掉那条龙，并将加热过的上古之刃插入她的尸体中。$B$B完成这些之后，奎尔塞拉就是你的了。",goals={},r={},ch={},xp=9950,money=0,changed="",changedc="",new=false,drop=false,rep={{"辛德拉",200}}},
  [7604]={n="A Binding Contract",c="瑟银兄弟会契约",lv=60,req=60,side="B",share=false,d="brd",wing="",cls={},st={k="item",id=18628,n="Thorium Brotherhood Contract",c="瑟银兄弟会契约",z=0,zc="",ze="",ui=0,x=0,y=0},fi={k="npc",id=12944,n="Lokhtos Darkbargainer",c="罗克图斯·暗契",z=1584,zc="黑石深渊",ze="Blackrock Depths",ui=0,x=0,y=0,i=true},stText="",stTextC="",pre={},preAny={},chain={},bread=false,o="Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.",oc="如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。",goals={{k="item",id=18628,n="Thorium Brotherhood Contract",c="瑟银兄弟会契约",cnt=1},{k="item",id=17203,n="Sulfuron Ingot",c="萨弗隆铁锭",cnt=1}},r={18592},ch={},xp=6600,money=0,changed="",changedc="",new=false,drop=false,rep={{"瑟银兄弟会",200},{"瑟银兄弟会",200},{"瑟银兄弟会",200},{"瑟银兄弟会",200}}},
  [7667]={n="Material Assistance",c="收集材料",lv=60,req=58,side="H",share=false,d="",wing="",cls={"7"},st={k="npc",id=13417,n="Sagorne Creststrider",c="萨格尼",z=1637,zc="奥格瑞玛",ze="Orgrimmar",ui=1454,x=38.6,y=36.2},fi={k="npc",id=13417,n="Sagorne Creststrider",c="萨格尼",z=1637,zc="奥格瑞玛",ze="Orgrimmar",ui=1454,x=38.6,y=36.2},stText="",stTextC="",pre={},preAny={},chain={7667,8258},bread=false,o="If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond .",oc="如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。",goals={},r={},ch={},xp=4950,money=0,changed="",changedc="",new=false,drop=false,rep={{"部落",150}}},
  [7668]={n="The Darkreaver Menace",c="暗缚者的威胁",lv=60,req=58,side="H",share=false,d="scholomance",wing="",cls={"7"},st={k="npc",id=13417,n="Sagorne Creststrider",c="萨格尼",z=1637,zc="奥格瑞玛",ze="Orgrimmar",ui=1454,x=38.6,y=36.2},fi={k="npc",id=13417,n="Sagorne Creststrider",c="萨格尼",z=1637,zc="奥格瑞玛",ze="Orgrimmar",ui=1454,x=38.6,y=36.2},stText="Shaman Only - Orgrimmar, Valley of Wisdom",stTextC="仅萨满祭司 - 奥格瑞玛，智慧谷",pre={7667},preAny={},chain={},bread=false,o="Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him. Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.",oc="在通灵学院大藏骨堂地下室中央使用预言水晶，打败召唤出的灵魂后会引出死亡骑士暗缚者，击败他，把暗缚者的头颅交给奥格瑞玛智慧谷的萨格隆·丘行者。",goals={{k="item",id=18880,n="Darkreaver's Head",c="达克雷尔的头颅",cnt=1}},r={18807},ch={},xp=9950,money=0,changed="",changedc="",new=false,drop=false,rep={{"部落",200}}},
  [7703]={n="Unfinished Gordok Business",c="戈多克食人魔的事务",lv=60,req=56,side="B",share=false,d="diremaul",wing="north",cls={},st={k="npc",id=14325,n="Captain Kromcrush",c="克罗卡斯",z=2557,zc="厄运之槌",ze="Dire Maul",ui=0,x=0,y=0,i=true},fi={k="npc",id=14325,n="Captain Kromcrush",c="克罗卡斯",z=2557,zc="厄运之槌",ze="Dire Maul",ui=0,x=0,y=0,i=true},stText="Dire Maul, North - Captain Kromcrush",stTextC="厄运之槌，北区 - 克罗卡斯上尉",pre={},preAny={},chain={},bread=false,o="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul . According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",oc="找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。$B$B根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。",goals={{k="item",id=18336,n="Gauntlet of Gordok Might",c="戈多克力量护手",cnt=1}},r={},ch={},xp=8300,money=0,changed="Rewards: no longer Choice of Gordok's Gauntlets, Choice of Gordok's Gloves, Choice of Gordok's Handguards, and 1 more",changedc="奖励去掉：可选 戈多克手甲、可选 戈多克手套、可选 戈多克护手、and 1 more",new=false,drop=false,rep={}},
  [7761]={n="Blackhand's Command",c="黑手的命令",lv=60,req=55,side="B",share=false,d="ubrs",wing="",cls={},st=nil,fi={k="object",id=179880,n="Drakkisath's Brand",c="达基萨斯的烙印",z=1583,zc="黑石塔",ze="Blackrock Spire",ui=0,x=0,y=0,i=true},stText="Blackrock Mountain, Side hallway on way to BWL - an item dropped by",stTextC="黑石山，去黑翼之巢路上的侧廊 - 一件物品，掉落自",pre={},preAny={},chain={},bread=false,o="That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command. The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.",oc="真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。$B$B你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。",goals={},r={},ch={},xp=6600,money=0,changed="",changedc="",new=false,drop=true,rep={}},
